program='''from collections import Counter

def transform(grid):
    """Connect collinear pixels of the sole non-background color."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return []
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foregrounds = set(counts) - {background}
    if len(foregrounds) != 1:
        return [row[:] for row in grid]
    foreground = next(iter(foregrounds))
    output = [row[:] for row in grid]

    # Draw between the leftmost and rightmost foreground pixels in each row.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == foreground]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == background:
                    output[r][c] = 3

    # Draw between the topmost and bottommost foreground pixels in each column.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == foreground]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == background:
                    output[r][c] = 3
    return output
'''
